import{_ as l,a0 as t,w as r,s as d,ao as p,I as o,a1 as i,A as e,x as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"moro：一个用于追踪工作时间的命令行生产力工具 | LCTT x X-CMD","titleTemplate":false,"description":"moro：一个用于追踪工作时间的命令行生产力工具 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"moro：一个用于追踪工作时间的命令行生产力工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"moro：一个用于追踪工作时间的命令行生产力工具 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180319 A Command Line Productivity Tool For Tracking Work Hours","title":"moro：一个用于追踪工作时间的命令行生产力工具","tag":"201805","desc":""},"relativePath":"201805/20180319 A Command Line Productivity Tool For Tracking Work Hours.md","filePath":"[post].md"}'),h={name:"201805/20180319 A Command Line Productivity Tool For Tracking Work Hours.md"};function c(k,s,g,u,b,m){const n=t("Link");return r(),d("div",null,[s[14]||(s[14]=p('<h1 id="moro-一个用于追踪工作时间的命令行生产力工具" tabindex="-1">moro：一个用于追踪工作时间的命令行生产力工具 <a class="header-anchor" href="#moro-一个用于追踪工作时间的命令行生产力工具" aria-label="Permalink to “moro：一个用于追踪工作时间的命令行生产力工具”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/03/Moro-720x340.jpg" alt=""></p><p>保持对你的工作小时数的追踪将让你知晓在一个特定时间区间内你所完成的工作总量。在网络上有大量的基于 GUI 的生产力工具可以用来追踪工作小时数。但我却不能找到一个基于 CLI 的工具。今天我偶然发现了一个简单而奏效的叫做 Moro 的追踪工作时间数的工具。Moro 是一个芬兰词汇，意为“Hello”。通过使用 Moro，你可以找到你在完成某项特定任务时花费了多少时间。这个工具是自由开源软件，它是通过 NodeJS 编写的。</p><h3 id="moro-一个追踪工作时间的命令行生产力工具" tabindex="-1">Moro - 一个追踪工作时间的命令行生产力工具 <a class="header-anchor" href="#moro-一个追踪工作时间的命令行生产力工具" aria-label="Permalink to “Moro - 一个追踪工作时间的命令行生产力工具”">​</a></h3><p>由于 Moro 是使用 NodeJS 编写的，保证你的系统上已经安装了 NodeJS。如果你没有安装好 NodeJS，跟随下面的链接在你的 Linux 中安装 NodeJS 和 NPM。</p>',5)),o("ul",null,[o("li",null,[i(n,{href:"https://www.ostechnix.com/install-node-js-linux/"},{default:e(()=>[...s[0]||(s[0]=[a("如何在 Linux 上安装 NodeJS",-1)])]),_:1})])]),s[15]||(s[15]=p(`<p>NodeJS 和NPM一旦装好，运行下面的命令来安装 Moro。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ npm install -g moro</span></span></code></pre></div><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h3><p>Moro 的工作概念非常简单。它记录了你的工作开始时间，结束时间和在你的系统上的休息时间。在每天结束时，它将会告知你已经工作了多少时间。</p><p>当你到达办公室时，只需键入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>♥ Moro \\o/</span></span>
<span class="line"><span>√ You clocked in at: 9:20</span></span></code></pre></div><p>Moro 将会把这个时间注册为你的开始时间。</p><p>当你离开办公室时，再次键入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>♥ Moro \\o/</span></span>
<span class="line"><span>√ You clocked out at: 19:22</span></span>
<span class="line"><span>ℹ Today looks like this so far:</span></span>
<span class="line"><span>┌──────────────────┬─────────────────────────┐</span></span>
<span class="line"><span>│ Today you worked │ 9 Hours and 72 Minutes │</span></span>
<span class="line"><span>├──────────────────┼─────────────────────────┤</span></span>
<span class="line"><span>│ Clock in │ 9:20 │</span></span>
<span class="line"><span>├──────────────────┼─────────────────────────┤</span></span>
<span class="line"><span>│ Clock out │ 19:22 │</span></span>
<span class="line"><span>├──────────────────┼─────────────────────────┤</span></span>
<span class="line"><span>│ Break duration │ 30 minutes │</span></span>
<span class="line"><span>├──────────────────┼─────────────────────────┤</span></span>
<span class="line"><span>│ Date │ 2018-03-19 │</span></span>
<span class="line"><span>└──────────────────┴─────────────────────────┘</span></span>
<span class="line"><span>ℹ Run moro --help to learn how to edit your clock in, clock out or break duration for today</span></span></code></pre></div><p>Moro 将会把这个时间注册为你的结束时间。</p><p>现在，Moro 将会从结束时间减去开始时间，然后从总的时间减去另外的 30 分钟作为休息时间，并给你在那天总的工作时间。抱歉，我的数学计算过程解释实在糟糕。假设你在早上 10:00 来工作并在晚上 17:30 离开。所以，你总共在办公室呆了 7:30 小时（例如 17:30-10）。然后在总的时间减去休息时间（默认是 30 分钟）。因此，你的总工作时间是 7 小时。明白了？很好！</p><p><strong>注意：</strong>不要像我在写这个手册的时候一样把 “moro” 和 “more” 弄混了。</p><p>查看你注册的所有小时数，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro report --all</span></span></code></pre></div><p>以防万一，如果你忘记注册开始时间或者结束时间，你一样可以在之后指定这些值。</p><p>例如，将上午 10 点注册为开始时间，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro hi 10:00</span></span>
<span class="line"><span>♥ Moro \\o/</span></span>
<span class="line"><span>√ You clocked in at: 10:00</span></span>
<span class="line"><span>⏰ Working until 18:00 will make it a full (7.5 hours) day</span></span></code></pre></div><p>注册 17:30 作为结束时间：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro bye 17:30</span></span>
<span class="line"><span>♥ Moro \\o/</span></span>
<span class="line"><span>√ You clocked out at: 17:30</span></span>
<span class="line"><span>ℹ Today looks like this so far:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>┌──────────────────┬───────────────────────┐</span></span>
<span class="line"><span>│ Today you worked │ 7 Hours and 0 Minutes │</span></span>
<span class="line"><span>├──────────────────┼───────────────────────┤</span></span>
<span class="line"><span>│ Clock in │ 10:00 │</span></span>
<span class="line"><span>├──────────────────┼───────────────────────┤</span></span>
<span class="line"><span>│ Clock out │ 17:30 │</span></span>
<span class="line"><span>├──────────────────┼───────────────────────┤</span></span>
<span class="line"><span>│ Break duration │ 30 minutes │</span></span>
<span class="line"><span>├──────────────────┼───────────────────────┤</span></span>
<span class="line"><span>│ Date │ 2018-03-19 │</span></span>
<span class="line"><span>└──────────────────┴───────────────────────┘</span></span>
<span class="line"><span>ℹ Run moro --help to learn how to edit your clock in, clock out or break duration for today</span></span></code></pre></div><p>你已经知道 Moro 默认将会减去 30 分钟的休息时间。如果你需要设置一个自定义的休息时间，你可以简单使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro break 45</span></span></code></pre></div><p>现在，休息时间是 45 分钟了。</p><p>若要清除所有的数据：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro clear --yes</span></span>
<span class="line"><span>♥ Moro \\o/</span></span>
<span class="line"><span>√ Database file deleted successfully</span></span></code></pre></div><h4 id="添加笔记" tabindex="-1">添加笔记 <a class="header-anchor" href="#添加笔记" aria-label="Permalink to “添加笔记”">​</a></h4><p>有时候，你想要在工作时添加笔记。不必去寻找一个独立的作笔记的应用。Moro 将会帮助你添加笔记。要添加笔记，只需运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro note mynotes</span></span></code></pre></div><p>要在之后搜索所有已经注册的笔记，只需做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro search mynotes</span></span></code></pre></div><h4 id="修改默认设置" tabindex="-1">修改默认设置 <a class="header-anchor" href="#修改默认设置" aria-label="Permalink to “修改默认设置”">​</a></h4><p>默认的完整工作时间是 7.5 小时。这是因为开发者来自芬兰，这是官方的工作小时数。但是你也可以修改这个设置为你的国家的工作小时数。</p><p>举个例子，要将其设置为 7 小时，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro config --day 7</span></span></code></pre></div><p>同样地，默认的休息时间也可以像下面这样从 30 分钟修改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro config --break 45</span></span></code></pre></div><h4 id="备份你的数据" tabindex="-1">备份你的数据 <a class="header-anchor" href="#备份你的数据" aria-label="Permalink to “备份你的数据”">​</a></h4><p>正如我已经说了的，Moro 将时间追踪信息存储在你的家目录，文件名是 <code>.moro-data.db</code>。</p><p>但是，你可以保存备份数据库到不同的位置。要这样做的话，像下面这样将 <code>.moro-data.db</code> 文件移到你选择的一个不同的位置并告知 Moro 使用那个数据库文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro config --database-path /home/sk/personal/moro-data.db</span></span></code></pre></div><p>在上面的每一个命令，我都已经把默认的数据库文件分配到了 <code>/home/sk/personal</code> 目录。</p><p>需要帮助的话，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro --help</span></span></code></pre></div><p>正如你所见，Moro 是非常简单而又能用于追踪你完成你的工作使用了多少时间的。对于自由职业者和任何想要在一定时间范围内完成事情的人，它将会是有用的。</p><p>并且，这些只是今天的内容。希望这些内容能够有所帮助。更多的好东西将会出现。请保持关注！</p><p>干杯！</p><hr>`,50)),o("p",null,[s[2]||(s[2]=a("via: ",-1)),i(n,{href:"https://www.ostechnix.com/moro-a-command-line-productivity-tool-for-tracking-work-hours/"},{default:e(()=>[...s[1]||(s[1]=[a("https://www.ostechnix.com/moro-a-command-line-productivity-tool-for-tracking-work-hours/",-1)])]),_:1})]),o("p",null,[s[6]||(s[6]=a("作者：",-1)),i(n,{href:"https://www.ostechnix.com/author/sk/"},{default:e(()=>[...s[3]||(s[3]=[a("SK",-1)])]),_:1}),s[7]||(s[7]=a(" 译者：",-1)),i(n,{href:"https://github.com/leemeans"},{default:e(()=>[...s[4]||(s[4]=[a("leemeans",-1)])]),_:1}),s[8]||(s[8]=a(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),o("p",null,[s[11]||(s[11]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[9]||(s[9]=[a("LCTT",-1)])]),_:1}),s[12]||(s[12]=a(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...s[10]||(s[10]=[a("Linux中国",-1)])]),_:1}),s[13]||(s[13]=a(" 荣誉推出",-1))])])}const x=l(h,[["render",c]]);export{C as __pageData,x as default};
